class Solution {
  private int best;

  public int longestConsecutive(TreeNode root) {
    walk(root);
    return best;
  }

  // {longest increasing path going down from node, longest decreasing path going down from node}
  private int[] walk(TreeNode node) {
    if (node == null) return new int[2];
    int inc = 1, dec = 1;
    for (TreeNode child : new TreeNode[] {node.left, node.right}) {
      if (child == null) continue;
      int[] c = walk(child);
      if (child.val == node.val + 1) inc = Math.max(inc, c[0] + 1);
      if (child.val == node.val - 1) dec = Math.max(dec, c[1] + 1);
    }
    best = Math.max(best, inc + dec - 1); // a path may turn at this node
    return new int[] {inc, dec};
  }
}
